INSERT INTO public.cursos_malla VALUES ('MAT101', 'Cálculo Diferencial', 4, 1, 'Ciencias Básicas', 'Límites, derivadas y aplicaciones en ingeniería.');
INSERT INTO public.cursos_malla VALUES ('SIS101', 'Fundamentos de Programación', 3, 1, 'Núcleo', 'Lógica algorítmica y programación estructurada en Python.');
INSERT INTO public.cursos_malla VALUES ('SIS102', 'Introducción a la Ingeniería de Sistemas', 2, 1, 'Núcleo', 'Panorama de la disciplina, pensamiento sistémico y ética.');
INSERT INTO public.cursos_malla VALUES ('MAT102', 'Cálculo Integral', 4, 2, 'Ciencias Básicas', 'Técnicas de integración y series.');
INSERT INTO public.cursos_malla VALUES ('MAT103', 'Álgebra Lineal', 3, 2, 'Ciencias Básicas', 'Matrices, espacios vectoriales y transformaciones lineales.');
INSERT INTO public.cursos_malla VALUES ('SIS201', 'Programación Orientada a Objetos', 3, 2, 'Núcleo', 'Clases, herencia, polimorfismo y patrones básicos en Java.');
INSERT INTO public.cursos_malla VALUES ('SIS301', 'Estructuras de Datos', 3, 3, 'Núcleo', 'Listas, pilas, colas, árboles, grafos y complejidad algorítmica.');
INSERT INTO public.cursos_malla VALUES ('MAT201', 'Matemáticas Discretas', 3, 3, 'Ciencias Básicas', 'Lógica proposicional, teoría de conjuntos, combinatoria y grafos.');
INSERT INTO public.cursos_malla VALUES ('SIS401', 'Bases de Datos I', 3, 4, 'Núcleo', 'Modelado entidad-relación, normalización y SQL.');
INSERT INTO public.cursos_malla VALUES ('SIS402', 'Análisis y Diseño de Algoritmos', 3, 4, 'Núcleo', 'Divide y vencerás, programación dinámica y algoritmos voraces.');
INSERT INTO public.cursos_malla VALUES ('SIS501', 'Ingeniería de Software I', 3, 5, 'Núcleo', 'Ciclo de vida del software, requisitos y metodologías ágiles (Scrum).');
INSERT INTO public.cursos_malla VALUES ('SIS502', 'Sistemas Operativos', 3, 5, 'Núcleo', 'Gestión de procesos, memoria, concurrencia y sistemas de archivos.');
INSERT INTO public.cursos_malla VALUES ('SIS601', 'Arquitectura en la Nube', 3, 6, 'Núcleo', 'Servicios cloud IaaS/PaaS/SaaS, contenedores y despliegue en AWS/Azure.');
INSERT INTO public.cursos_malla VALUES ('CCD101', 'Fundamentos de Ciencia de Datos e IA', 3, 6, 'Competencias Digitales', 'Análisis exploratorio, modelos predictivos y ruta de insignia digital CCD.');
INSERT INTO public.cursos_malla VALUES ('SIS701', 'Inteligencia Artificial y Aprendizaje Automático', 3, 7, 'Núcleo', 'Redes neuronales, LLMs, procesamiento de lenguaje natural y agentes.');


