-- Data for Name: faq_academicas; Type: TABLE DATA; Schema: public; Owner: unab_admin
--

INSERT INTO public.faq_academicas VALUES (1, 'Matrícula', 'cancelar materia,retiro asignatura,cancelacion', '¿Cuál es el plazo y proceso para cancelar una materia?', 'Puedes solicitar la cancelación de asignaturas desde el portal Cosmos/Banner dentro de las fechas establecidas en el calendario académico semestral, siempre que no superes el límite de créditos mínimos ni hayas reprobado la materia por fallas.', true);
INSERT INTO public.faq_academicas VALUES (2, 'Grado', 'opciones de grado,trabajo de grado,tesis,practica', '¿Cuáles son las modalidades de trabajo de grado en Ingeniería de Sistemas UNAB?', 'En Ingeniería de Sistemas puedes optar por: Proyecto de Investigación, Práctica Empresarial, Coterminal (materias de posgrado) o Emprendimiento, cumpliendo con los créditos aprobados exigidos por el plan de estudios.', true);
INSERT INTO public.faq_academicas VALUES (3, 'Reglamento', 'prueba academica,promedio minimo,bajo rendimiento', '¿Cuándo entra un estudiante en prueba académica?', 'Un estudiante entra en período de prueba académica cuando su promedio ponderado acumulado o semestral cae por debajo del mínimo exigido en el Reglamento Estudiantil de Pregrado UNAB (3.0).', true);
INSERT INTO public.faq_academicas VALUES (4, 'Homologación', 'homologar,validacion,transferencia', '¿Cómo solicito homologación o validación de una asignatura?', 'Debes radicar la solicitud ante la Dirección del Programa adjuntando el contenido programático oficial y el certificado de notas antes del inicio del período de matrícula.', true);
INSERT INTO public.faq_academicas VALUES (5, 'Bienestar', 'tutorias,monitorias,apoyo academico', '¿Dónde solicito monitorías o tutorías académicas?', 'Puedes agendar monitorías académicas gratuitas a través del programa de Permanencia y Éxito Estudiantil (Bienestar Universitario UNAB) o directamente con los monitores asignados por la facultad.', true);


