INSERT INTO public.n8n_chat_histories_unab VALUES (16, 'unab_1794995278668_ravisxy', '{"type": "ai", "content": "Los profesores del programa de Ingeniería de Sistemas que se encuentran activos actualmente en la base de datos son:\n\n| Nombre Completo | Departamento | Área de Especialidad | Correo Institucional |\n| :--- | :--- | :--- | :--- |\n| Carlos Eduardo Mendoza Ríos | Ingeniería de Sistemas | Bases de Datos e Ingeniería de Software | cmendoza@unab.edu.co |\n| Laura Patricia Gómez Salcedo | Ingeniería de Sistemas | Inteligencia Artificial y Ciencia de Datos | lgomez@unab.edu.co |\n| Andrés Felipe Villamizar Peña | Ingeniería de Sistemas | Redes, Cloud Computing y Ciberseguridad | avillamizar@unab.edu.co |\n| Diana Carolina Rueda Ortiz | Ingeniería de Sistemas | Desarrollo Web y Tecnologías Móviles | drueda@unab.edu.co |\n| Jorge Hernán Castellanos Silva | Ingeniería de Sistemas | Arquitectura de Software y Sistemas Operativos | jcastellanos@unab.edu.co |\n\nSi necesitas información sobre sus horarios de atención u oficina, no dudes en consultármelo.", "tool_calls": [], "additional_kwargs": {}, "response_metadata": {}, "invalid_tool_calls": []}');
